class Solution {
private:
    struct Point { double x, y; };
    struct Circle { double x, y, r; };

    double dist(Point a, Point b) {
        return hypot(a.x - b.x, a.y - b.y);
    }

    Circle getCircle(const vector<Point>& R) {
        if (R.empty()) return {0, 0, 0};
        if (R.size() == 1) return {R[0].x, R[0].y, 0};
        if (R.size() == 2) {
            double cx = (R[0].x + R[1].x) / 2.0;
            double cy = (R[0].y + R[1].y) / 2.0;
            return {cx, cy, dist(R[0], {cx, cy})};
        }
        double x1 = R[0].x, y1 = R[0].y;
        double x2 = R[1].x, y2 = R[1].y;
        double x3 = R[2].x, y3 = R[2].y;
        double d = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
        if (abs(d) < 1e-9) return {0, 0, 0};
        double ux = ((x1 * x1 + y1 * y1) * (y2 - y3) + (x2 * x2 + y2 * y2) * (y3 - y1) + (x3 * x3 + y3 * y3) * (y1 - y2)) / d;
        double uy = ((x1 * x1 + y1 * y1) * (x3 - x2) + (x2 * x2 + y2 * y2) * (x1 - x3) + (x3 * x3 + y3 * y3) * (x2 - x1)) / d;
        return {ux, uy, dist(R[0], {ux, uy})};
    }

    Circle welzl(vector<Point>& P, int n, vector<Point> R) {
        if (n == 0 || R.size() == 3) return getCircle(R);
        Circle c = welzl(P, n - 1, R);
        if (dist(P[n - 1], {c.x, c.y}) <= c.r + 1e-7) return c;
        R.push_back(P[n - 1]);
        return welzl(P, n - 1, R);
    }

public:
    vector<double> enclose(vector<vector<int>>& trees) {
        vector<Point> P;
        for (const auto& t : trees) P.push_back({(double)t[0], (double)t[1]});
        mt19937 g(42);
        shuffle(P.begin(), P.end(), g);
        Circle c = welzl(P, P.size(), {});
        return {c.x, c.y, c.r};
    }
