class Solution {
    private static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    private static class Circle {
        double x, y, r;
        Circle(double x, double y, double r) { this.x = x; this.y = y; this.r = r; }
    }

    private double dist(Point a, Point b) {
        return Math.hypot(a.x - b.x, a.y - b.y);
    }

    private Circle getCircle(List<Point> R) {
        if (R.isEmpty()) return new Circle(0, 0, 0);
        if (R.size() == 1) return new Circle(R.get(0).x, R.get(0).y, 0);
        if (R.size() == 2) {
            double cx = (R.get(0).x + R.get(1).x) / 2.0;
            double cy = (R.get(0).y + R.get(1).y) / 2.0;
            return new Circle(cx, cy, dist(R.get(0), new Point(cx, cy)));
        }
        double x1 = R.get(0).x, y1 = R.get(0).y;
        double x2 = R.get(1).x, y2 = R.get(1).y;
        double x3 = R.get(2).x, y3 = R.get(2).y;
        double d = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
        if (Math.abs(d) < 1e-9) return new Circle(0, 0, 0);
        double ux = ((x1 * x1 + y1 * y1) * (y2 - y3) + (x2 * x2 + y2 * y2) * (y3 - y1) + (x3 * x3 + y3 * y3) * (y1 - y2)) / d;
        double uy = ((x1 * x1 + y1 * y1) * (x3 - x2) + (x2 * x2 + y2 * y2) * (x1 - x3) + (x3 * x3 + y3 * y3) * (x2 - x1)) / d;
        return new Circle(ux, uy, dist(R.get(0), new Point(ux, uy)));
    }

    private Circle welzl(List<Point> P, int n, List<Point> R) {
        if (n == 0 || R.size() == 3) return getCircle(R);
        Circle c = welzl(P, n - 1, R);
        if (dist(P.get(n - 1), new Point(c.x, c.y)) <= c.r + 1e-7) return c;
        List<Point> nextR = new ArrayList<>(R);
        nextR.add(P.get(n - 1));
        return welzl(P, n - 1, nextR);
    }

    public double[] enclose(int[][] trees) {
        List<Point> P = new ArrayList<>();
        for (int[] t : trees) P.add(new Point(t[0], t[1]));
        Collections.shuffle(P, new Random(42));
        Circle c = welzl(P, P.size(), new ArrayList<>());
        return new double[]{c.x, c.y, c.r};
    }
}

var enclose = function(trees) {
  const P = trees.map(([x, y]) => ({ x, y }));
  for (let i = P.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [P[i], P[j]] = [P[j], P[i]];
  }

  function dist(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y);
  }

  function getCircle(R) {
    if (R.length === 0) return { x: 0, y: 0, r: 0 };
    if (R.length === 1) return { x: R[0].x, y: R[0].y, r: 0 };
    if (R.length === 2) {
      const cx = (R[0].x + R[1].x) / 2;
      const cy = (R[0].y + R[1].y) / 2;
      return { x: cx, y: cy, r: dist(R[0], { x: cx, y: cy }) };
    }
    const [p1, p2, p3] = R;
    const d = 2 * (p1.x * (p2.y - p3.y) + p2.x * (p3.y - p1.y) + p3.x * (p1.y - p2.y));
    if (Math.abs(d) < 1e-9) return { x: 0, y: 0, r: 0 };
    const ux = ((p1.x ** 2 + p1.y ** 2) * (p2.y - p3.y) + (p2.x ** 2 + p2.y ** 2) * (p3.y - p1.y) + (p3.x ** 2 + p3.y ** 2) * (p1.y - p2.y)) / d;
    const uy = ((p1.x ** 2 + p1.y ** 2) * (p3.x - p2.x) + (p2.x ** 2 + p2.y ** 2) * (p1.x - p3.x) + (p3.x ** 2 + p3.y ** 2) * (p2.x - p1.x)) / d;
    return { x: ux, y: uy, r: dist(p1, { x: ux, y: uy }) };
  }

  function welzl(n, R) {
    if (n === 0 || R.length === 3) return getCircle(R);
    const c = welzl(n - 1, R);
    if (dist(P[n - 1], { x: c.x, y: c.y }) <= c.r + 1e-7) return c;
    return welzl(n - 1, R.concat([P[n - 1]]));
  }

  const c = welzl(P.length, []);
  return [c.x, c.y, c.r];
};
